-- ter_code_system（建表 + 种子数据）
-- Flyway V66

CREATE TABLE IF NOT EXISTS ter_code_system (
    id BIGINT PRIMARY KEY,
    name VARCHAR(100) NOT NULL UNIQUE,
    title VARCHAR(200),
    description TEXT,
    version VARCHAR(50) DEFAULT '1.0',
    status int4 NOT NULL,
    tenant_id BIGINT,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP,
    created_by BIGINT,
    updated_by BIGINT,
    is_deleted BOOLEAN NOT NULL DEFAULT FALSE,
    deleted_at TIMESTAMP,
    deleted_by BIGINT
);

CREATE INDEX IF NOT EXISTS idx_code_system_tenant_id ON ter_code_system(tenant_id);

CREATE INDEX IF NOT EXISTS idx_code_system_status ON ter_code_system(status);

CREATE INDEX IF NOT EXISTS idx_code_system_created_at ON ter_code_system(created_at);

CREATE INDEX IF NOT EXISTS idx_code_system_is_deleted ON ter_code_system(is_deleted);

COMMENT ON COLUMN ter_code_system.name IS '编码系统名称（对应原来的dictType）';

COMMENT ON COLUMN ter_code_system.title IS '编码系统标题（人类可读）';

COMMENT ON COLUMN ter_code_system.version IS '版本号（如：1.0, 1.1, 2.0）';

COMMENT ON COLUMN ter_code_system.status IS '状态：DRAFT（草稿）、ACTIVE（活跃）、RETIRED（已废弃）';

ALTER TABLE ter_code_system
    ALTER COLUMN status TYPE VARCHAR(255) USING status::VARCHAR;

-- seed: ter_code_system
ON CONFLICT ("id") DO NOTHING;

ON CONFLICT ("id") DO NOTHING;

ON CONFLICT ("id") DO NOTHING;
